// Combat backgrounds. Art is generated by tools/art/zones/<id>.ts into
// public/assets/zones/<id>/; this registry holds how the zone behaves at runtime.
// Adding one: see .claude/skills/new-combat-background.
import { FactionId, ZoneDef } from './types';

export const ZONES: ZoneDef[] = [
  {
    // Zone 1 from Jakub's working notes, redesigned on his brief (2026-10-11): dawn in autumn,
    // a burning field, a broken cart, a rift torn in the cosmos; leaves blowing in the wind
    id: 'zone1',
    name: 'Fracture Reach',
    ambient: 'leaves',
    glow: [255, 150, 70],
    shadow: { dx: 4, stretch: 1.25 },
    tint: { color: '#ff9a60', alpha: 0.05, op: 'soft-light' },
    // ravens wheeling over the burnt farm and the windmill, and more over the burning field on the left (2026-10-12)
    birds: 7,
    birdsAt: [[316, 80], [100, 50], [150, 68]],
    // Jakub, 2026-10-12: "maybe from time to time, very unfrequently you can light up the sky in weird colors for a moment";
    // it spreads from the rift (tools/art/zones/zone1.ts RIFT_TOP / RIFT_BOT)
    // Jakub, the same day: "more frequent, instead of 24-52s maybe rather go for 10-25s"
    flash: { at: [536, 78], every: [10000, 25000], ms: 1700, colors: ['#4affc0', '#ff4ad8', '#9a6aff', '#ffb04a', '#4ad8ff'] },
  },
  {
    // Zone 2 from Jakub's working notes, painted on his brief (2026-10-12): an overgrown place of statues and
    // columns in the jungle on a sunlit day, old temples on a table mountain, serpents carved on the wall in
    // front of its stair, many trees in the foreground; pollen drifting in the light
    id: 'zone2',
    name: 'Verdant Grove',
    ambient: 'pollen',
    glow: [255, 226, 160],
    // the sun stands high: short shadows
    shadow: { dx: 2, stretch: 1.1 },
    tint: { color: '#ffe8a8', alpha: 0.05, op: 'soft-light' },
    // Jakub: "on the sky we can have some details as well, maybe birds and cloud": macaws wheeling over the jungle
    birds: 4,
    birdsAt: [[226, 48], [372, 24]],
    // Jakub: "maybe few butterflies"
    butterflies: [[84, 232], [290, 176], [588, 214], [196, 108], [470, 96]],
  },
  {
    // Zone 3, named and described by Jakub (2026-10-17): the Moonlit Basin beyond the trailing roots of the
    // Verdant Grove, "a new dynamic zone": night under the moon, glowing twilight-moss, glass reeds swaying
    // without a breeze, tide-pools, dust-motes of bioluminescent flora drifting in pearlescent halos
    id: 'zone3',
    name: 'Moonlit Basin',
    ambient: 'spores',
    // nothing burns here; the colour a light pool would take
    glow: [170, 210, 255],
    // the moon stands high in the upper left: short, soft shadows
    shadow: { dx: 3, stretch: 1.15 },
    tint: { color: '#8ea4ff', alpha: 0.06, op: 'soft-light' },
    // a first take: now and then a shooting star, rarely
    shootingStars: [14000, 32000],
  },
  {
    // Zone 4, named and described by Jakub (2026-10-18): Earth Scars, the easternmost place, a steppe by day cut by
    // deep ravines; yurts with small colourful flags like a vertical chain on very long poles, a few wild yaks
    // roaming nearby, a very big mountain with a snowy peak and its lower twin far off, a distant zeppelin in the
    // sky, "some parts moving"; feather-grass seeds sailing on the wind
    id: 'zone4',
    name: 'Earth Scars',
    ambient: 'seeds',
    // nothing burns here; the colour a light pool would take
    glow: [255, 226, 168],
    // the sun stands high in the upper left: short shadows thrown to the right
    shadow: { dx: 3, stretch: 1.15 },
    tint: { color: '#ffe6b0', alpha: 0.04, op: 'soft-light' },
    // a first take: steppe eagles circling over the ravine and the far steppe
    birds: 3,
    birdsAt: [[150, 86], [520, 64]],
  },
];

const byId = new Map(ZONES.map((z) => [z.id, z]));

/**
 * The zone a faction calls home: where its champions stand in the Academy
 * demos and on their detail page. The Court of Root's is the Verdant Grove,
 * inside its territory (docs/DESIGN_DECISIONS.md 5.4); every other faction
 * stands in the first zone.
 */
export function homeZone(faction: FactionId): ZoneDef {
  return faction === 'court_of_root' ? zone('zone2') : ZONES[0];
}

export function zone(id: string): ZoneDef {
  const z = byId.get(id);
  if (!z) throw new Error(`unknown zone "${id}"`);
  return z;
}
